#pragma once

#include <cstddef>
#include <cstring>

// mod's pixel shaders, compiled when the mod is built. Every src/shader/hlsl/<name>.hlsl is compiled by fxc (see CMakeLists.txt) and the
// bytecode is embedded into the DLL (cmake/embed_shaders.cmake), so the mod stays a single file and nothing is compiled at runtime.
namespace ssa::CompiledShaders
{
    struct Shader
    {
        const char* name; // the name of the .hlsl file without the extension
        const unsigned char* data; // 4 byte aligned, the bytecode is read as DWORDs
        size_t size;
    };

    // generated by cmake/embed_shaders.cmake: every compiled shader, followed by an entry with a null name
    extern const Shader kShaders[];

    // the compiled shader hlsl/<name>.hlsl, null if there is none
    inline const Shader* Find(const char* name)
    {
        for (const Shader* shader = kShaders; shader->name; ++shader)
            if (std::strcmp(shader->name, name) == 0)
                return shader;
        return nullptr;
    }
} // namespace ssa::CompiledShaders
